import type React from "react"
import {
  ArrowUpRight,
  Award,
  CircleDot,
  Globe,
  type LucideIcon,
} from "lucide-react"
import { Section } from "@/components/section"
import { experience } from "@/data/profile"

interface BadgeProps {
  icon: LucideIcon
  children: React.ReactNode
}

const Badge = ({ icon: Icon, children }: BadgeProps) => (
  <span className="inline-flex items-center gap-1 rounded-full border border-primary/30 bg-primary/10 px-2.5 py-0.5 text-xs font-semibold text-accent print:hidden">
    <Icon aria-hidden="true" strokeWidth={2} className="size-3" />
    {children}
  </span>
)

export const Experience = () => (
  <Section
    id="experience"
    index="02"
    label="Experience"
    title="Where I’ve worked"
  >
    <ol className="divide-y divide-line-soft border-y border-line-soft">
      {experience.map((job) => (
        <li
          key={job.company}
          className="reveal grid gap-2 py-8 transition-colors hover:bg-ink/[0.02] sm:grid-cols-[180px_1fr] sm:gap-10 sm:px-4"
        >
          <p className="font-mono text-sm text-ink-muted tabular-nums sm:pt-1">
            {job.period}
          </p>
          <div>
            <div className="flex flex-wrap items-center gap-2">
              <h3 className="text-xl font-semibold">
                {job.url ? (
                  <a
                    href={job.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="group inline-flex items-center gap-1 text-ink hover:text-accent"
                  >
                    {job.company}
                    <ArrowUpRight
                      aria-hidden="true"
                      strokeWidth={1.75}
                      className="size-4 text-ink-muted transition-[color,translate] group-hover:-translate-y-0.5 group-hover:translate-x-0.5 group-hover:text-accent"
                    />
                  </a>
                ) : (
                  job.company
                )}
              </h3>
              {job.current && <Badge icon={CircleDot}>Current</Badge>}
              {job.note && <Badge icon={Award}>{job.note}</Badge>}
              {job.remote && <Badge icon={Globe}>Remote</Badge>}
            </div>
            <p className="mt-1 font-medium text-accent">{job.role}</p>
            {job.summary && (
              <p className="mt-3 max-w-2xl text-ink-muted">{job.summary}</p>
            )}
          </div>
        </li>
      ))}
    </ol>
  </Section>
)
