import type React from "react"
import type { LucideIcon } from "lucide-react"

interface SectionLabelProps {
  index: string
  children: React.ReactNode
  className?: string
}

export const SectionLabel = ({
  index,
  children,
  className = "",
}: SectionLabelProps) => (
  <p
    className={`flex items-center gap-3 font-mono text-xs uppercase tracking-[0.2em] text-accent print:hidden ${className}`}
  >
    <span className="text-ink-muted">{index}</span>
    <span aria-hidden="true" className="h-px w-8 bg-primary/50" />
    {children}
  </p>
)

interface SectionProps {
  id: string
  index: string
  label: string
  title: string
  children: React.ReactNode
}

/** A consistently-styled, anchorable content section. */
export const Section = ({
  id,
  index,
  label,
  title,
  children,
}: SectionProps) => (
  <section id={id} className="border-t border-line-soft">
    <div className="mx-auto max-w-6xl px-5 py-24 sm:py-28">
      <header className="reveal mb-12 sm:mb-16">
        <SectionLabel index={index}>{label}</SectionLabel>
        <h2 className="mt-4 max-w-3xl text-3xl font-semibold tracking-tight sm:text-5xl">
          {title}
        </h2>
      </header>
      {children}
    </div>
  </section>
)

interface ChipProps {
  children: React.ReactNode
  icon?: LucideIcon
}

export const Chip = ({ children, icon: Icon }: ChipProps) => (
  <span className="chip inline-flex items-center gap-1.5 rounded-full border border-line bg-ink/[0.03] px-3 py-1 text-sm text-ink-soft transition-colors hover:border-primary/50 hover:text-ink">
    {Icon && (
      <Icon
        aria-hidden="true"
        strokeWidth={1.75}
        className="size-3.5 text-accent"
      />
    )}
    {children}
  </span>
)

export const IconTile = ({ icon: Icon }: { icon: LucideIcon }) => (
  <span
    aria-hidden="true"
    className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-accent ring-1 ring-primary/20 print:hidden"
  >
    <Icon strokeWidth={1.75} className="size-5" />
  </span>
)

export const Card = ({
  children,
  className = "",
}: {
  children: React.ReactNode
  className?: string
}) => (
  <div
    className={`reveal spotlight rounded-2xl border border-line bg-surface-raised p-6 shadow-[inset_0_1px_0_0_rgb(255_255_255/0.04)] transition-colors hover:border-primary/40 ${className}`}
  >
    {children}
  </div>
)
